public class Solution {
  public static long admitRequest(long tokensMicro, long elapsedMicros, long ratePerSecMicro, long capacityMicro, long costMicro) {
    if (tokensMicro < 0) throw new IllegalArgumentException("dirty bucket state");
    if (costMicro < 0) throw new IllegalArgumentException("negative cost");
    if (costMicro > capacityMicro) throw new IllegalArgumentException("cost exceeds capacity: can never be admitted");

    long tokens = tokensMicro;
    if (elapsedMicros > 0 && ratePerSecMicro > 0 && capacityMicro > 0 && tokens < capacityMicro) {
      long need = capacityMicro - tokens;            // 正值且 <= capacityMicro，不会溢出
      // 补满所需的最长微秒数；用它把"必然补满"的情况挡在乘法之前
      long saturateAt = need * 1_000_000L / ratePerSecMicro + 1;
      if (elapsedMicros >= saturateAt) {
        tokens = capacityMicro;
      } else if (elapsedMicros > Long.MAX_VALUE / ratePerSecMicro) {
        tokens = capacityMicro;                      // 乘法会溢出：elapsed 已小于 saturateAt，说明 rate 极大，直接视为补满
      } else {
        long add = elapsedMicros * ratePerSecMicro / 1_000_000L;
        tokens = Math.min(capacityMicro, tokens + add);   // 两项均 < Long.MAX_VALUE，加法不溢出
      }
    }

    tokens = Math.min(tokens, capacityMicro);        // 脏余额（高于容量）一律截到容量，不得被放大
    if (tokens < costMicro) return tokens;           // 拒绝：返回补充后的余额，不返回负数
    return tokens - costMicro;
  }
}

